const getPriorityAnimationUrlsForBuilding = (building: Pick<PlacedBuilding, 'buildingId' | 'workState' | 'workEndTime'>): string[] => {
    const isWorking = building.workState === 'working' && !!building.workEndTime;

    if (TOWN_HALL_FLAG_ID_SET.has(building.buildingId)) return townHallFlagAnimationFrames[building.buildingId] || [];
    if (FLAG_ANIMATION_ID_SET.has(building.buildingId)) return flagAnimationFrames[building.buildingId] || [];
    if (FINANCIAL_INTELLIGENCE_ID_SET.has(building.buildingId)) return financialIntelligenceAnimationFrames[building.buildingId] || [];
    if (building.buildingId === DETONATOR_FACTORY_ID && isWorking) return detonatorFactoryAnimationFrames;
    if (building.buildingId === DEVIL_MACHINE_ID && isWorking) return devilMachineAnimationFrames;
    if (building.buildingId === MILL_ID && isWorking) return millAnimationFrames;
    if (building.buildingId === CHAN_VAT_BUILDING_ID && isWorking) return chanWorkingAnimationFrames;
    if (building.buildingId === TREBUCHET_ID) {
        return [
            ...trebuchetLoadingUpRightFrames,
            ...trebuchetLoadingUpLeftFrames,
            ...trebuchetLoadingDownLeftFrames,
            ...trebuchetLoadingDownRightFrames,
            ...trebuchetLaunchUpRightFrames,
            ...trebuchetLaunchUpLeftFrames,
            ...trebuchetLaunchDownLeftFrames,
            ...trebuchetLaunchDownRightFrames,
            ...trebuchetMoveUpRightFrames,
            ...trebuchetMoveUpLeftFrames,
            ...trebuchetMoveDownLeftFrames,
            ...trebuchetMoveDownRightFrames,
            TREBUCHET_IDLE_UP_RIGHT,
            TREBUCHET_IDLE_UP_LEFT,
            TREBUCHET_IDLE_DOWN_LEFT,
            TREBUCHET_IDLE_DOWN_RIGHT,
            TREBUCHET_LOADED_UP_RIGHT,
            TREBUCHET_LOADED_UP_LEFT,
            TREBUCHET_LOADED_DOWN_LEFT,
            TREBUCHET_LOADED_DOWN_RIGHT
        ];
    }
    if (building.buildingId === MORTAR_ID) return mortarFlashFrames;
    if (COIN_FACTORY_ID_SET.has(building.buildingId) && isWorking) return coinFactoryAnimationFrames[building.buildingId] || [];
    if (SAWMILL_ID_SET.has(building.buildingId) && isWorking) return sawmillAnimationFrames[building.buildingId] || [];

    if (MONSTER_ACADEMY_ID_SET.has(building.buildingId)) {
        const group = MONSTER_ACADEMY_ID_TO_GROUP[building.buildingId];
        if (group) return isWorking ? monsterAcademyWorkingFrames[group.folder] : (monsterAcademyIdleFrames[group.folder]?.[0] ? [monsterAcademyIdleFrames[group.folder][0]] : []);
    }

    if (ALCHEMY_FACTORY_ID_SET.has(building.buildingId)) {
        return isWorking ? (alchemyFactoryWorkingFrames[building.buildingId] || []) : (alchemyFactoryIdleFrames[building.buildingId]?.[0] ? [alchemyFactoryIdleFrames[building.buildingId][0]] : []);
    }

    if (MILITARY_FACTORY_ID_SET.has(building.buildingId) && isWorking) return militaryFactoryAnimationFrames;

    if (MUSHROOM_BED_ID_SET.has(building.buildingId)) {
        const group = MUSHROOM_BED_ID_TO_GROUP[building.buildingId];
        if (group) return isWorking ? mushroomBedWorkingFrames[group.folder] : (mushroomBedIdleFrames[group.folder]?.[0] ? [mushroomBedIdleFrames[group.folder][0]] : []);
    }

    if (MINE_ID_SET.has(building.buildingId)) {
        const group = MINE_ID_TO_GROUP[building.buildingId];
        if (group) return isWorking ? mineWorkingFrames[group.folder] : (mineIdleFrames[group.folder]?.[0] ? [mineIdleFrames[group.folder][0]] : []);
    }

    if (EMERALD_FACTORY_ID_SET.has(building.buildingId)) {
        const group = EMERALD_FACTORY_ID_TO_GROUP[building.buildingId];
        if (group) return isWorking ? emeraldFactoryWorkingFrames[group.folder] : (emeraldFactoryIdleFrames[group.folder]?.[0] ? [emeraldFactoryIdleFrames[group.folder][0]] : []);
    }

    if (GOLD_SMELTER_ID_SET.has(building.buildingId)) {
        const group = GOLD_SMELTER_ID_TO_GROUP[building.buildingId];
        if (group) {
            if (isWorking) return goldSmelterWorkingFrames[group.folder] || [];
            if (group.idleFrames > 0 && goldSmelterIdleFrames[group.folder]?.[0]) return [goldSmelterIdleFrames[group.folder][0]];
        }
    }

    if (STEEL_ROLLING_MILL_ID_SET.has(building.buildingId)) {
        const group = STEEL_ROLLING_MILL_ID_TO_GROUP[building.buildingId];
        if (group) return isWorking ? steelRollingMillWorkingFrames[group.folder] : (steelRollingMillIdleFrames[group.folder]?.[0] ? [steelRollingMillIdleFrames[group.folder][0]] : []);
    }

    if (STEEL_SMELTING_ID_SET.has(building.buildingId)) {
        return isWorking ? (steelSmeltingWorkingFrames[building.buildingId] || []) : (steelSmeltingIdleFrames[building.buildingId]?.[0] ? [steelSmeltingIdleFrames[building.buildingId][0]] : []);
    }

    if (STONE_CRUSHER_ID_SET.has(building.buildingId)) {
        const folder = STONE_CRUSHER_ID_TO_FOLDER[building.buildingId];
        if (folder) return isWorking ? stoneCrusherWorkingFrames[folder] : (stoneCrusherIdleFrames[folder]?.[0] ? [stoneCrusherIdleFrames[folder][0]] : []);
    }

    if (LILY_POND_ID_SET.has(building.buildingId)) {
        const group = LILY_POND_ID_TO_GROUP[building.buildingId];
        if (group) return isWorking ? lilyPondWorkingFrames[group.folder] : (lilyPondIdleFrames[group.folder]?.[0] ? [lilyPondIdleFrames[group.folder][0]] : []);
    }

    if (DETONATOR_FACTORY_ID_SET.has(building.buildingId)) {
        const group = DETONATOR_FACTORY_ID_TO_GROUP[building.buildingId];
        if (group) {
            if (isWorking) return detonatorFactoryWorkingFrames[group.folder] || [];
            if (group.idleFrames > 0 && detonatorFactoryIdleFrames[group.folder]?.[0]) return [detonatorFactoryIdleFrames[group.folder][0]];
        }
    }

    if (building.buildingId === WILD_QUARRY_ID && isWorking) return wildQuarryAnimationFrames;
    if (building.buildingId === RECOMMENDATION_FACTORY_ID && isWorking) return recommendationFactoryAnimationFrames;
    if ((building.buildingId === OIL_RIG_ID || building.buildingId === TWO_OIL_RIGS_ID) && isWorking) return oilRigAnimationFrames[building.buildingId] || [];
    if (building.buildingId === GIFT_LAMB_ID) return giftLambAnimationFrames;
    if (building.buildingId === GIFT_SLIPPER_ID) return giftSlipperAnimationFrames;

    // Monster sprites use special scale / offsets in the renderer, so we must keep
    // their animation frames available nearby instead of falling back to static card art.
    if (building.buildingId === KILLING_HUT_ID) {
        return [
            ...izbushkaIdleFrames,
            ...izbushkaWalkLeftFrames,
            ...izbushkaWalkRightFrames,
            ...izbushkaWalkDownFrames,
            ...izbushkaWalkUpFrames,
            ...izbushkaAttackTopFrames,
            ...izbushkaAttackLeftFrames,
            ...izbushkaAttackBottomFrames,
            ...izbushkaAttackRightFrames,
            ...izbushkaCancelTopFrames,
            ...izbushkaCancelLeftFrames,
            ...izbushkaCancelBottomFrames,
            ...izbushkaCancelRightFrames,
        ];
    }

    if (building.buildingId === KIND_SANTA_ID) {
        return [
            ...santaIdleFrames,
            ...santaWalkLeftFrames,
            ...santaWalkDownFrames,
            ...santaWalkRightFrames,
            ...santaWalkUpFrames,
            ...santaAttackLeftFrames,
            ...santaAttackBottomFrames,
            ...santaAttackRightFrames,
            ...santaAttackTopFrames,
        ];
    }

    if (building.buildingId === BRONEKUR_ID) {
        return [
            ...bronekurIdleFrames,
            ...bronekurWalkBottomFrames,
            ...bronekurWalkTopRightFrames,
            ...bronekurWalkLeftTopFrames,
            ...bronekurWalkBottomRightFrames,
            ...bronekurAttackTopFrames,
            ...bronekurAttackLeftFrames,
            ...bronekurAttackBottomFrames,
            ...bronekurAttackRightFrames,
        ];
    }

    if (building.buildingId === GORYNYCH_ID) {
        return [
            ...gorynychIdleFrames,
            ...gorynychWalkUpFrames,
            ...gorynychWalkDownFrames,
            ...gorynychWalkLeftFrames,
            ...gorynychWalkRightFrames,
            ...gorynychAttackTopFrames,
            ...gorynychAttackBottomFrames,
            ...gorynychAttackLeftFrames,
            ...gorynychAttackRightFrames,
        ];
    }

    if (building.buildingId === KOLOBOK_ID) {
        return [
            ...kolobokIdleFrames,
            ...kolobokWalkUpFrames,
            ...kolobokWalkDownFrames,
            ...kolobokWalkLeftFrames,
            ...kolobokWalkRightFrames,
            ...kolobokAttackTopFrames,
            ...kolobokAttackLeftFrames,
            ...kolobokAttackBottomFrames,
            ...kolobokAttackRightFrames,
        ];
    }

    if (building.buildingId === BABA_YAGA_ID) {
        return [
            ...babaYagaIdleFrames,
            ...babaYagaWalkUpFrames,
            ...babaYagaWalkDownFrames,
            ...babaYagaWalkLeftFrames,
            ...babaYagaWalkRightFrames,
            ...babaYagaAttackTopFrames,
            ...babaYagaAttackLeftFrames,
            ...babaYagaAttackBottomFrames,
            ...babaYagaAttackRightFrames,
        ];
    }

    const customAnimSpec = getCustomMonsterAnimationSpec(building.buildingId);
    if (customAnimSpec) {
        return customAnimSpec.allAnimationFrames;
    }

    switch (building.buildingId) {
        case BABY_BEAR_MAX_ID: return babyBearAnimationFrames;
        case BABY_ANGEL_GIRL_MAX_ID: return babyAngelGirlAnimationFrames;
        case BABY_DINO_MAX_ID: return babyDinoAnimationFrames;
        case BABY_PIGLET_MAX_ID: return babyPigletAnimationFrames;
        case BABY_CAT_MAX_ID: return babyCatAnimationFrames;
        case BABY_ANGEL_BOY_MAX_ID: return babyAngelBoyAnimationFrames;
        case BABY_PANDA_MAX_ID: return babyPandaAnimationFrames;
        case BABY_FROG_MAX_ID: return babyFrogAnimationFrames;
        default: return [];
    }
};

// Function to draw animated coin
const drawAnimatedCoin = (ctx: CanvasRenderingContext2D, x: number, y: number, size: number, time: number) => {
    const rotation = (time / 500) % (Math.PI * 2); // Full rotation in 500ms
    const scaleX = Math.cos(rotation); // Simulate 3D rotation
    const stretch = 0.3; // How thin the coin gets at edges
    const actualWidth = size * (stretch + (1 - stretch) * Math.abs(scaleX));
    
    ctx.save();
    ctx.translate(x, y);
    
    // Coin body gradient
    const gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, size * 0.5);
    gradient.addColorStop(0, '#FFF8DC');
    gradient.addColorStop(0.3, '#FFD700');
    gradient.addColorStop(0.7, '#DAA520');
    gradient.addColorStop(1, '#B8860B');
    
    // Draw coin ellipse (simulating rotation)
    ctx.beginPath();
    ctx.ellipse(0, 0, actualWidth * 0.5, size * 0.5, 0, 0, Math.PI * 2);
    ctx.fillStyle = gradient;
    ctx.fill();
    
    // Coin edge (3D effect)
    ctx.strokeStyle = '#8B6914';
    ctx.lineWidth = Math.max(2, size * 0.08);
    ctx.stroke();
    
    // Shimmer effect
    const shimmerOffset = ((time % 1000) / 1000) * actualWidth;
    const shimmerGrad = ctx.createLinearGradient(-actualWidth * 0.5 + shimmerOffset - 20, 0, -actualWidth * 0.5 + shimmerOffset + 20, 0);
    shimmerGrad.addColorStop(0, 'rgba(255, 255, 255, 0)');
    shimmerGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.6)');
    shimmerGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');
    
    ctx.beginPath();
    ctx.ellipse(0, 0, actualWidth * 0.48, size * 0.48, 0, 0, Math.PI * 2);
    ctx.fillStyle = shimmerGrad;
    ctx.fill();
    
    // Letter B in center (only visible when facing forward)
    if (Math.abs(scaleX) > 0.3) {
        ctx.fillStyle = '#8B6914';
        ctx.font = `bold ${Math.round(size * 0.42)}px serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('B', 0, 0);
    }
    
    ctx.restore();
};

// Function to draw swirling loading spinner matching the UI Swirling component
const drawLoadingSpinner = (ctx: CanvasRenderingContext2D, x: number, y: number, size: number, time: number) => {
    const r = size / 2;
    const swirlRadius = Math.max(2, r * 0.65);
    const strokeWidth = Math.max(1.8, swirlRadius * 0.28);
    
    ctx.save();
    ctx.translate(x, y);
    
    // Dark background circle with subtle border for contrast on game map
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(10, 10, 10, 0.92)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';
    ctx.lineWidth = Math.max(1, 1.2 * (size / 20));
    ctx.stroke();

    // Faint circular track
    ctx.beginPath();
    ctx.arc(0, 0, swirlRadius, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';
    ctx.lineWidth = strokeWidth;
    ctx.stroke();

    // Swirling dash & spin animation (exact formula from Swirling component):
    // Duration: dash 1.5s (alternate cycle = 3.0s), spin = 1.5s * 1.333333 = 2.0s
    const tNorm = (time % 3000) / 1500;
    const p = tNorm <= 1 ? tNorm : 2 - tNorm;
    const eased = 0.5 - 0.5 * Math.cos(Math.PI * p);
    
    let theta1: number;
    let theta2: number;
    if (eased <= 0.5) {
        const k = eased / 0.5;
        theta1 = 0 + 1.0 * k;
        theta2 = 0.005 + (3.0 - 0.005) * k;
    } else {
        const k = (eased - 0.5) / 0.5;
        theta1 = 1.0 + (4.0 - 1.0) * k;
        theta2 = 3.0 + (8.0 - 3.0) * k;
    }

    const spinAngle = ((time % 2000) / 2000) * Math.PI * 2;
    const startAngle = spinAngle + theta1;
    const endAngle = spinAngle + theta2;

    // Draw swirling animated arc
    ctx.beginPath();
    ctx.arc(0, 0, swirlRadius, startAngle, endAngle);
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = strokeWidth;
    ctx.lineCap = 'round';
    ctx.stroke();
    
    ctx.restore();
};

// Format time in Russian style: 5м 17с, 1ч 19м, 1д 19ч 32м
const formatTimeRussian = (ms: number): string => {
    const totalSeconds = Math.floor(ms / 1000);
    const days = Math.floor(totalSeconds / 86400);
    const hours = Math.floor((totalSeconds % 86400) / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    
    if (days > 0) {
        return `${days}д ${hours}ч ${minutes}м`;
    } else if (hours > 0) {
        return `${hours}ч ${minutes}м`;
    } else {
        return `${minutes}м ${seconds}с`;
    }
};

