    const [shouldAutoScroll, setShouldAutoScroll] = useState(false); // Auto-scroll disabled
    const phasedLoadingTriggeredRef = useRef(false); // Guard against stale closure re-triggering chat open
    useEffect(() => { playerGloryRef.current = playerGlory; }, [playerGlory]);
