    // Royal Election Timer & Winner Selection
    useEffect(() => {
        if (royalElectionEndTime === 0) return;

        const checkRoyalElection = async () => {
            const now = Date.now();
            const timeLeft = royalElectionEndTime - now;

            if (timeLeft <= 0) {
                // Election ended - determine winners by gender
                if (Object.keys(royalCandidates).length > 0) {
                    // Separate candidates by gender
                    const maleCandidates = Object.entries(royalCandidates)
                        .filter(([uid]) => allUsers[uid]?.gender === 'male')
                        .sort(([, a], [, b]) => b - a);
                    
                    const femaleCandidates = Object.entries(royalCandidates)
                        .filter(([uid]) => allUsers[uid]?.gender === 'female')
                        .sort(([, a], [, b]) => b - a);
                    
                    // King is the male with most votes
                    const [kingWinnerId, kingVotes] = maleCandidates[0] || [null, 0];
                    // Queen is the female with most votes
                    const [queenWinnerId, queenVotes] = femaleCandidates[0] || [null, 0];
                    
                    if (kingWinnerId && kingVotes > 0) {
                        const kingWinnerName = allUsers[kingWinnerId]?.name || 'Король';
                        const queenWinnerName = queenWinnerId ? (allUsers[queenWinnerId]?.name || 'Королева') : null;
                        
                        // Calculate next election time (30 days from now)
                        const nextElectionTime = Date.now() + 2592000000;
                        
                        // Update Firebase
                        const electionData = {
                            candidates: {},
                            kingId: kingWinnerId,
                            kingName: kingWinnerName,
                            queenId: queenWinnerId || null,
                            queenName: queenWinnerName || null,
                            votesTotal: 0,
                            electionEndTime: nextElectionTime,
                            firstElectionCompleted: true
                        };
                        
                        try {
                            await setDoc(doc(db, 'elections', 'royal'), electionData);
                            
                            // Send system message to general chat
                            const msgId = `royal-elected-${Date.now()}`;
                            let messageText = `👑 Поздравляем! Новым Королем города стал ${kingWinnerName} с ${kingVotes} голосами!`;
                            if (queenWinnerName) {
                                messageText += ` Королевой стала ${queenWinnerName} с ${queenVotes} голосами!`;
                            }
                            await setDoc(doc(db, 'chat_messages', msgId), {
                                sender: '[СИСТЕМА]',
                                senderId: 'system',
                                text: messageText,
                                type: 'system',
                                timestamp: Date.now(),
                                tab: 'general'
                            });
                        } catch (e) {
                            console.error('Failed to complete royal election:', e);
                        }
                    }
                }
            }
        };

        const interval = setInterval(checkRoyalElection, 10000); // Check every 10 seconds
        checkRoyalElection(); // Initial check

        return () => clearInterval(interval);
    }, [royalElectionEndTime, royalCandidates, allUsers, firstRoyalElectionCompleted]);

